mapper.sql:
where member_id = #{memberId}

    and change_type = #{changeType}


    and create_time >= #{beginTime}


    and create_time < #{endTime}

where member_id = #{memberId}

    and amount_type = #{amountType}


    and create_time >= #{beginTime}


    and create_time < #{endTime}

trim.if:
select 'order' as type, order_no as bizNo,
       concat('订单 ', ifnull(member_name, '')) as title,
       pay_amount as amount, null as pointChange,
       coalesce(finish_time, pay_time, create_time) as eventTime,
       concat('pages/order/detail?orderId=', order_id) as linkUrl
from biz_order
where member_id = #{memberId}

    and coalesce(finish_time, pay_time, create_time) >= #{beginTime}


    and coalesce(finish_time, pay_time, create_time) < #{endTime}

union all
select 'borrow' as type, borrow_no as bizNo, title,
       null as amount, null as pointChange, borrow_time as eventTime,
       concat('pages/borrow/detail?borrowId=', borrow_id) as linkUrl
from biz_borrow
where member_id = #{memberId}

    and borrow_time >= #{beginTime}


    and borrow_time < #{endTime}

union all
select 'point' as type, ref_no as bizNo,
       concat('积分', if(points_change >= 0, '获得', '变动')) as title,
       null as amount, points_change as pointChange, create_time as eventTime,
       'pages/member/point/logs' as linkUrl
from biz_point_log
where member_id = #{memberId}

    and create_time >= #{beginTime}


    and create_time < #{endTime}

union all
select 'recycle' as type, recycle_no as bizNo, '二手书回收' as title,
       coalesce(nullif(final_amount, 0), estimated_amount) as amount,
       null as pointChange, coalesce(settle_time, submit_time, create_time) as eventTime,
       concat('pages/recycle/detail?recycleId=', recycle_id) as linkUrl
from biz_recycle
where member_id = #{memberId}

    and coalesce(settle_time, submit_time, create_time) >= #{beginTime}


    and coalesce(settle_time, submit_time, create_time) < #{endTime}

mapper.select:
select
    ifnull((select sum(pay_amount) from biz_order where member_id = #{memberId}
            and status not in (5, 7)), 0) as totalConsume,
    (select count(*) from biz_borrow where member_id = #{memberId}) as totalBorrow,
    ifnull((select sum(points_change) from biz_point_log where member_id = #{memberId}
            and points_change > 0), 0) as totalPointsGained

mapper.sql:
where member_id = #{memberId}

    and msg_type = #{msgType}


    and is_read = #{readStatus}

mapper.update:
update biz_message set is_read = 1, read_time = now() where member_id = #{memberId} and is_read = 0
and message_id in
#{id}

mapper.select:
select
    (select count(*) from biz_borrow where member_id = #{memberId}
     and status in (1, 3)) as activeBorrows,
    (select count(*) from biz_order where member_id = #{memberId}
     and status not in (5, 7) and (is_settled is null or is_settled = 0)) as pendingOrders,
    (select count(*) from biz_recycle where member_id = #{memberId}
     and status in (1, 2)) as pendingRecycles
